// === Tab: Plane ===
class Plane{
	constructor(x,y){
		this.position = createVector(x,y);
		this.x=x;
		this.y=y;
		this.isFlying=false;
		this.speed = random(5,8);
		this.direction=createVector(0,0);
		this.velocity=createVector(0,0);
		this.rotation=0;
		this.seed=random(1,8)
		this.trail=[];

		// this.col=col;
	}

	update(){
		if(!this.isFlying){
			this.position.x=(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
			this.position.y=(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
		}else{
			//update plane position and rotation
			let noiseOffsetX = map(noise(frameCount * 0.01, this.seed), 0, 1, -0.05, 0.05);
      let noiseOffsetY = map(noise(frameCount * 0.01 + 1000, this.seed), 0, 1, -0.05, 0.05);
			let wave = sin(frameCount * 0.05) * 0.2; 
      let noiseVector = createVector(noiseOffsetX+wave, noiseOffsetY);
			this.direction=this.direction.add(noiseVector);
			this.direction.normalize();
			this.velocity=this.direction.mult(this.speed);
			//print(this.velocity.y);
			this.position.add(this.velocity);
			this.rotation=this.velocity.heading()+ radians(45);

			//update trail
			if(frameCount%6==0){
				this.trail.unshift(createVector(this.position.x,this.position.y));				
			}

			//if out of bound
			if (this.position.y < -height/2||this.position.x>3*width/2) {
				this.isFlying=false;
				this.rotation=0
			}
		}
	}



	draw(){
		noStroke();
		//draw trail
		if(this.isFlying){
			for(let i=1;i<this.trail.length;i++){
				fill(255, 255, 255,255-i*15);
				ellipse(this.trail[i].x,this.trail[i].y,8);
			}}
		//draw plane	
		push();
    translate(this.position.x, this.position.y);
    rotate(this.rotation);
		fill('#F6FAFD');
		triangle(0, 0, -140, + 55, -100, 75);
		fill('#CEDEEB');
		triangle(0, 0, -100,  75, -90, 120);
		fill('#F6FAFD');
		triangle(0, 0, -80, 85, -20, 125);
		fill('#AEC7DB');
		triangle(-80, 85, -90, 120,-60,98);
		pop();


		}



}

